#!/usr/bin/env python3
import os, sys, json, urllib.request, subprocess
URL='https://raw.githubusercontent.com/gschaidergabriel/clay-global-research-entity/d3c8f7a1f9901c0478fd6331844f87d61eb8eb10/handoff/avatar-body-shoulder-microkinematics-20260912/body_live_gpu_shadow_gate.py'
EXPECTED='18770d8e333af1bc49a818da4dbd5c2e482b859e0142d0213df6c956184c931e'
def prod():
    out=[]
    for n in os.listdir('/proc'):
        if not n.isdigit(): continue
        try: a=open('/proc/'+n+'/cmdline','rb').read().replace(b'\x00',b' ').decode('utf-8','replace')
        except OSError: continue
        if '--app=http://127.0.0.1:8788/' in a and 'chrome-profile' in a: out.append(int(n))
    return sorted(out)
before=prod()
print('PRODUCTION_BEFORE='+json.dumps(before))
os.environ['DISPLAY']=':0'
src=urllib.request.urlopen(URL,timeout=20).read().decode('utf-8')
needle="cmd=[a.chrome,'--headless=new','--no-sandbox','--use-gl=angle','--disable-background-networking','--no-first-run',f'--user-data-dir={td/\"profile\"}',f'--window-size=900,700',f'http://127.0.0.1:{srv.server_address[1]}/buehne.html']"
repl="cmd=[a.chrome,'--no-sandbox','--use-gl=angle','--disable-background-networking','--no-first-run',f'--user-data-dir={td/\"profile\"}','--window-size=746,449','--window-position=100,100',f'http://127.0.0.1:{srv.server_address[1]}/buehne.html']"
if src.count(needle)!=1:
    print('PATCH_ANCHOR_MISMATCH',src.count(needle)); sys.exit(7)
src=src.replace(needle,repl,1)
ns={'__name__':'__main__','__file__':'body_live_gpu_shadow_gate_visible_x11.py'}
rc=0
try:
    exec(compile(src,ns['__file__'],'exec'),ns)
except SystemExit as e:
    rc=int(e.code or 0)
after=prod()
print('PRODUCTION_AFTER='+json.dumps(after))
print('PRODUCTION_PID_INVARIANT='+str(before==after))
print('LIVE_EXPECTED_SHA='+EXPECTED)
if before!=after and rc==0: rc=11
sys.exit(rc)
